<?php $pageTitle='Orders';$subtitle='Review customers, payment, delivery and downloadable invoices.';$active='Orders';require __DIR__.'/_layout.php';$pdo=db();$orders=$pdo->query('SELECT o.*,COUNT(oi.id) item_count FROM orders o LEFT JOIN order_items oi ON oi.order_id=o.id GROUP BY o.id ORDER BY o.created_at DESC')->fetchAll();
?>
<div class="card"><div class="filters"><input class="input" id="q" placeholder="Search order, customer, phone, pincode..." oninput="searchOrders()"><select class="select" id="statusFilter" onchange="searchOrders()"><option value="">All statuses</option><?php foreach(['accepted','processing','packed','shipped','delivered','cancelled'] as $s):?><option><?=$s?></option><?php endforeach;?></select></div><div class="table-wrap"><table id="orders"><thead><tr><th>Order</th><th>Customer</th><th>Address</th><th>Amount</th><th>Payment</th><th>Status</th><th>Invoice</th></tr></thead><tbody><?php foreach($orders as $o):?><tr data-search="<?=ae(strtolower($o['order_number'].' '.$o['customer_name'].' '.$o['customer_phone'].' '.$o['pincode']))?>" data-status="<?=ae($o['order_status'])?>"><td><strong><?=ae($o['order_number'])?></strong><br><small><?=ae($o['created_at'])?></small><br><span class="pill blue"><?=number_format((int)$o['item_count'])?> items</span></td><td><?=ae($o['customer_name'])?><br><?=ae($o['customer_phone'])?><br><small><?=ae($o['customer_email'])?></small></td><td style="max-width:260px"><?=ae($o['address_line1'])?><br><?=ae($o['address_line2'])?><br><?=ae($o['city'])?>, <?=ae($o['state'])?> — <?=ae($o['pincode'])?></td><td><strong>₹<?=number_format((float)$o['total_amount'],2)?></strong><br><small>Subtotal ₹<?=number_format((float)$o['subtotal'],2)?><br>Coupon −₹<?=number_format((float)$o['coupon_discount'],2)?><br>GST <?=number_format((float)$o['tax_rate'],0)?>% · ₹<?=number_format((float)$o['tax_amount'],2)?></small></td><td><span class="pill <?=($o['payment_method']==='online'?'green':'gold')?>"><?=ae(strtoupper($o['payment_method']))?></span><br><small><?=ae(str_replace('_',' ',strtoupper($o['payment_status'])))?></small></td><td><select class="select" onchange="changeStatus(<?=$o['id']?>,this.value)"><?php foreach(['accepted','processing','packed','shipped','delivered','cancelled'] as $s):?><option value="<?=$s?>" <?=$o['order_status']===$s?'selected':''?>><?=$s?></option><?php endforeach;?></select></td><td><div class="actions"><a class="btn primary" target="_blank" href="../invoice.php?id=<?=$o['id']?>">View / Print</a><a class="btn" target="_blank" href="../invoice.php?id=<?=$o['id']?>&download=1">Download</a></div></td></tr><?php endforeach;if(!$orders):?><tr><td colspan="7" class="empty">No orders yet.</td></tr><?php endif;?></tbody></table></div></div><script>function searchOrders(){const q=document.querySelector('#q').value.toLowerCase(),s=document.querySelector('#statusFilter').value;document.querySelectorAll('#orders tbody tr').forEach(r=>r.style.display=(r.dataset.search.includes(q)&&(!s||r.dataset.status===s))?'':'none')}async function changeStatus(id,status){const j=await api('update-order-status',{order_id:id,status});toast(j.message,j.ok);if(j.ok){const r=[...document.querySelectorAll('#orders tbody tr')].find(x=>x.querySelector('select')?.getAttribute('onchange')?.includes('('+id+','));if(r)r.dataset.status=status}}</script><?php require __DIR__.'/_foot.php'; ?>
